package com.stark.automation.utils;
import com.stark.automation.config.ConfigurationManager; import com.stark.automation.core.driver.DriverFactory; import java.time.Duration; import org.openqa.selenium.By; import org.openqa.selenium.WebElement; import org.openqa.selenium.support.ui.ExpectedConditions; import org.openqa.selenium.support.ui.WebDriverWait;
public final class Waits { private Waits() { } private static WebDriverWait waitForDriver() { return new WebDriverWait(DriverFactory.getDriver(), Duration.ofSeconds(ConfigurationManager.integer("explicit.wait"))); } public static WebElement visible(By locator) { return waitForDriver().until(ExpectedConditions.visibilityOfElementLocated(locator)); } public static void clickable(By locator) { waitForDriver().until(ExpectedConditions.elementToBeClickable(locator)); } public static void urlContains(String value) { waitForDriver().until(ExpectedConditions.urlContains(value)); } }
